format_code:
chip esp32

hardware {
    pin led: Output = 2
}

shared var counter: int = 0

task inc {
    every 100ms { counter += 1 }
}

task reader {
    every 1s {
        if counter > 10 {
            led.on()
        }
    }
}

system_graph.mermaid:
flowchart LR
    v_counter("counter")
    u_inc(("inc<br>↻ 100ms"))
    u_reader(("reader<br>↻ 1s"))
    u_inc -->|write| v_counter
    v_counter -.->|read| u_reader
